"""Seating charts: students sorted by last name."""

from typing import List
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    last = student.last_name.lower()
    return (last, student.first_name.lower())


def _chunks(items: list, size: int) -> list:
    return [
        items[start:start + size]
        for start in range(0, len(items), size)
    ]


def _render(rows: list) -> List[str]:
    return [
        f"Row {index}: " + " | ".join(
            f"{item.last_name}, {item.first_name}"
            for item in row
        )
        for index, row in enumerate(rows, 1)
    ]


# ---
def seat_rows(
    students: List[Student],
    seats: int
) -> List[str]:
    if seats <= 0 or not students:
        raise ProjectError("bad seating input")
    ordered = sorted(students, key=_sort_key)
    return _render(_chunks(ordered, seats))

