# owner: platform
import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id-" + last, last, first, "A")


class SeatRowsTests(unittest.TestCase):
    def test_sorts_and_splits_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Arkwright", "Tess")
        ]
        self.assertEqual(
            seat_rows(people, 2),
            [
                "Row 1: Arkwright, Tess | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_first_name_breaks_ties(self):
        people = [make("Gray", "Zed"), make("Gray", "Amy")]
        self.assertEqual(
            seat_rows(people, 5),
            ["Row 1: Gray, Amy | Gray, Zed"]
        )

    def test_bad_seat_counts(self):
        people = [make("Gray", "Amy")]
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seat_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)


if __name__ == "__main__":
    unittest.main()
